        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】1. 先針對題幹核心問題「回聲 0.5 秒後傳回，聲速 340 m/s，牆距離約？」進行分析：0.5 秒是來回時間，單程距離 340×0.5÷2＝85 m。\n2. 核對各選項與課綱判準：選項 (B) 準確指出「85 m」之結論，並完整扣合「音調」與「響度」的成立條件。\n3. 驗證遷移情境：若直接答 204 m 就把來回距離當單程；實際聲速還會隨介質與溫度改變，確認選項 (B) 推論嚴密無誤。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】逐項剖析錯誤選項之迷思：\n• (A) 錯誤：誤選混淆項「170 m」，且忽略了本課核心防線「聲音不能在真空中傳遞；越大聲不代表頻率越高」。\n• (C) 錯誤：將「頻率（每秒振動次數，主要影響音調…）」與「振幅（振動偏離平衡位置的幅度，與響度有關…）」的概念張冠李戴。\n• (D) 錯誤：在「頻率增加，主要改變聲音哪項性質？」中誤判為「音量必變大」（正確應為「音調變高」：音調主要由振動頻率決定，頻率越高音調越高）。",
        "【第 5 步：版本對照 · 跨版本教材提點與大考心法】康軒、翰林、南一三版本教材在「聲音與波動」均強調實作檢核任務：「用橡皮筋比較張力不同的音調，說明控制哪些條件」。大考遇到跨圖表或情境素養題時，務必先劃出「音調」與「響度」的成立條件，再排除違反「聲音不能在真空中傳遞；越大聲不代表頻率越高…」的誘答選項。"
