        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱「運動、力與牛頓定律」核心知識點：\n1. 牛頓第一定律（慣性）：合力為零時，靜者恆靜，動者恆作等速度直線運動；物體維持原有運動狀態的特性稱為慣性（實證檢核：汽車緊急煞車時乘客身體向前傾；甩動體溫計使水銀柱回位；拍打衣服抖落灰塵皆為慣性實例）。\n2. 牛頓第二定律 (F=ma)：物體受外力合力作用時，產生同方向加速度；a 與合力成正比，與質量 m 成反比（實證檢核：1 N 定義：使 1 kg 物體產生 1 m/s² 加速度之合力；合力加倍則加速度加倍）。\n3. 關鍵推理原則：平均速率＝總路程÷總時間；速度還包含方向。合力造成速度的改變，合力為零時可靜止或等速度運動。F＝ma 用一致單位計算。",
