        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱「物質進出細胞與酵素催化作用」核心知識點：\n1. 簡單擴散作用：分子由高濃度往低濃度自然淨移動，不消耗能量 (ATP)（實證檢核：氣體分子（O₂、CO₂）及脂溶性物質（甘油、脂肪酸）可直接穿透磷脂質雙層）。\n2. 促進性擴散（便利性擴散）：由高濃度往低濃度，需細胞膜上「膜蛋白（通道蛋白/載體蛋白）」協助，不耗能（實證檢核：葡萄糖、胺基酸及各類帶電礦物質離子進出細胞之主要被動運輸方式）。\n3. 關鍵推理原則：細胞膜具有選擇通透性。小分子如氧氣、二氧化碳可藉擴散作用直接通過脂雙層；水可透過滲透作用進出細胞。酵素是生物體內的蛋白質催化劑，具專一性，活性受溫度與 pH 值顯著影響。",
