        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】逐項剖析錯誤選項之迷思：\n• (A) 錯誤：誤選混淆項「酵素在 100°C 沸水中催化活性最高」，且忽略了本課核心防線「植物細胞置於純水不會破裂，因細胞壁提供機械支持抗膨壓；煮沸會使酵素蛋白質變性失去活性，降溫後無法恢復催化功能」。\n• (C) 錯誤：將「擴散（粒子有由高濃度區到低濃度區的淨移動趨勢…）」與「酵素作用（降低反應所需的活化障礙，本身不作為反應耗材…）」的概念張冠李戴。\n• (D) 錯誤：在「將人類紅血球置入蒸餾水中，一段時間後最可能發生的現象是？」中誤判為「細胞生成細胞壁」（正確應為「細胞膨脹甚至破裂」：蒸餾水濃度低於細胞質，水分子大量滲透進入紅血球內，因無細胞壁保護最終膨脹破裂）。",
