        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱「植物的體內運輸與水分恆定」核心知識點：\n1. 根部吸水：根部與外界水分交換須考慮水分條件及細胞膜（實證檢核：根毛增加接觸面積；不能說根靠主動吸力把整株水向上拉）。\n2. 木質部：主要運輸水與無機鹽（實證檢核：根吸收的水可沿木質部往葉片運輸）。\n3. 關鍵推理原則：維管束植物靠木質部與韌皮部進行運輸。木質部由下往上單向運送水分與礦物質，主要動力來自葉片氣孔的蒸散作用，輔以根壓與毛細現象；韌皮部負責運送葉片光合作用合成的蔗糖等有機養分，可雙向運送。",
