        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱「動物呼吸系統與排泄泌尿作用」核心知識點：\n1. 呼吸運動機制：吸氣時橫膈下降、肋骨上舉、胸腔容積增大、胸內壓減小，空氣入肺（實證檢核：呼氣時相反；呼吸由腦幹呼吸中樞依血液中 CO₂ 濃度調節）。\n2. 氣體交換原理：利用濃度差進行擴散作用，不耗能（實證檢核：肺泡與微血管間 O₂ 進入血液，CO₂ 進入肺泡；組織處相反）。\n3. 關鍵推理原則：呼吸系統進行氣體交換：吸氣時肋骨上提、橫膈下降，胸腔體積擴大、壓力降低，外界空氣進入肺泡；排泄系統排除細胞代謝產生的含氮廢物。蛋白質代謝產生有毒的氨，人體肝臟先將其轉化為毒性較低的尿素，再由腎臟過濾形成尿液排出。",
