        "【第 5 步：版本對照 · 跨版本教材提點與大考心法】康軒、翰林、南一三版本教材在「動物呼吸系統與排泄泌尿作用」均強調實作檢核任務：「利用寶特瓶、氣球與吸管製作胸腔呼吸模型，拉動底部氣球薄膜說明橫膈升降與肺泡氣壓體積之關係」。大考遇到跨圖表或情境素養題時，務必先劃出「呼吸運動機制」與「氣體交換原理」的成立條件，再排除違反「呼吸運動受血液中「二氧化碳濃度」主導調控，非缺氧為主；排…」的誘答選項。"
