        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱「浮力與阿基米德原理」核心知識點：\n1. 液體壓力公式：P = ρ · g · h（在同一均勻不可壓縮液體中，液壓僅與垂直深度 h 及液體密度 ρ 有關）（實證檢核：液壓無特定方向，任一點向四面八方壓力皆相等且垂直於容器接觸面；與容器形狀寬窄無關）。\n2. 連通管原理與帕斯卡定律：連通管各管液面在靜止時等高；密閉流體任一點所受壓力增量，等值傳遞至流體各處（實證檢核：液壓千斤頂：小活塞施小力 F₁/A₁，在大活塞 A₂ 產生巨大輸出推力 F₂ = F₁·(A₂/A₁)）。\n3. 關鍵推理原則：浸在流體中的物體受到向上的浮力，浮力大小等於物體所排開的流體重量（B＝V_排×D_液）。物體密度小於液體密度時上浮為浮體（B＝物重）；密度大於液體密度時下沉為沈體（B＝V_物×D_液＜物重）。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】1. 先針對題幹核心問題「同一顆鐵球先後放入純水（密度 1.0 g/cm³）與濃食鹽水（密度 1.2 g/cm³）中，鐵球皆沉入底部，則在何者中所受浮力較大？」進行分析：鐵球在兩液體中皆完全沒入（V_排相同），因食鹽水密度較大，依 B＝V_排×D_液，在食鹽水中浮力較大。\n2. 核對各選項與課綱判準：選項 (B) 準確指出「食鹽水中較大」之結論，並完整扣合「液體壓力公式」與「連通管原理與帕斯卡定律」的成立條件。\n3. 驗證遷移情境：「浮力等於物重」只適用於沒有其他鉛直力的平衡情境，不是任何浸水物體都成立，確認選項 (B) 推論嚴密無誤。",
