        "【第 5 步：版本對照 · 跨版本教材提點與大考心法】康軒、翰林、南一三版本教材在「摩擦力、正向力與牛頓第一運動定律深化」均強調實作檢核任務：「將木塊置於不同表面（桌面、砂紙、墊板），用彈簧秤測量剛拉動木塊瞬間的讀數，比較最大靜摩擦力」。大考遇到跨圖表或情境素養題時，務必先劃出「二力平衡條件」與「靜摩擦力 (fs)」的成立條件，再排除違反「物體未被推動時，靜摩擦力大小等於當時的「推力」，不等於最…」的誘答選項。"
