      "stem": "閱讀以下「反應速率與影響因素」之跨情境探究案例與對照資料：\n【情境案例與數據觀察】同質量碳酸鈣粉末與大顆粒分別加入足量、同濃度酸中，粉末較快產氣，是否代表最後氣體一定更多？\n【延伸實證紀錄】同質量的碳酸鈣，大理石粉末與鹽酸反應產生二氧化碳的速率遠快於整塊大理石塊；夏天食物容易腐壞是因為氣溫較高使化學與微生物分解反應速率加快。\n根據 108 課綱「理化・化學」核心知識點與判準，針對上述情境及「在雙氧水（H₂O₂）分解產生氧氣的實驗中加入二氧化錳（MnO₂），反應結束後二氧化錳的狀態應為？」之綜合判斷，下列敘述何者最為正確？",
