        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱「反應速率與影響因素」核心知識點：\n1. 有效碰撞條件：反應物粒子必須發生碰撞，且碰撞時「能量須大於低限活化能」且「碰撞方向位向正確」（實證檢核：反應速率定義為單位時間內反應物濃度的消耗量，或生成物濃度的增加量）。\n2. 反應物濃度與表面積：濃度越高或固體顆粒越細（接觸表面積越大），單位體積內粒子碰撞頻率越高，反應速率越快（實證檢核：粉末狀碳酸鈣與鹽酸反應速率遠快於大理石塊；麵粉廠粉塵飛揚極易引發粉塵爆炸）。\n3. 關鍵推理原則：化學反應速率衡量單位時間內反應物的消耗量或生成物的產生量。有效碰撞理論指出反應物粒子必須具有足夠能量與正確方向碰撞才能反應。影響速率的因素包括：反應物本性、接觸表面積（固體顆粒越小越快）、濃度（濃度越高碰撞機率越大）、溫度（升溫粒子動能增加且高能分子比例提升）與催化劑。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】1. 先針對題幹核心問題「在雙氧水（H₂O₂）分解產生氧氣的實驗中加入二氧化錳（MnO₂），反應結束後二氧化錳的狀態應為？」進行分析：二氧化錳在該反應中擔任催化劑，可加快反應速率，但自身質量與化學性質在反應前後均不改變。\n2. 核對各選項與課綱判準：選項 (B) 準確指出「質量與化學性質皆維持不變」之結論，並完整扣合「有效碰撞條件」與「反應物濃度與表面積」的成立條件。\n3. 驗證遷移情境：應畫氣體體積對時間圖：斜率表示速率，最後平台高度表示總量，確認選項 (B) 推論嚴密無誤。",
