        "【第 5 步：版本對照 · 跨版本教材提點與大考心法】康軒、翰林、南一三版本教材在「反應速率與影響因素」均強調實作檢核任務：「用等量發泡錠分別投入冰水、常溫水與溫水中，計時完全反應所需時間，繪製水溫與反應時間之關係圖」。大考遇到跨圖表或情境素養題時，務必先劃出「有效碰撞條件」與「反應物濃度與表面積」的成立條件，再排除違反「催化劑（如二氧化錳催化雙氧水分解）能改變反應途徑降低活化…」的誘答選項。"
