      "stem": "閱讀以下「電解質與阿瑞尼斯解離說」之跨情境探究案例與對照資料：\n【情境案例與數據觀察】同濃度食鹽水與糖水，哪種通常較能讓導電測試燈發亮？為什麼不能僅用透明與否判斷？\n【延伸實證紀錄】NaCl(s) 溶於水解離為 Na⁺ 與 Cl⁻，通電時陽離子向負極移動、陰離子向正極移動形成電流。蔗糖或乙醇（酒精）溶於水以分子狀態存在不解離，為非電解質。\n根據 108 課綱「理化・化學」核心知識點與判準，針對上述情境及「氯化鈣（CaCl₂）水溶液中含有大量的 Ca²⁺ 與 Cl⁻。關於該溶液中正負離子的敘述何者正確？」之綜合判斷，下列敘述何者最為正確？",
