        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱「酸鹼滴定與常見生活鹽類」核心知識點：\n1. 酸鹼中和反應：淨反應為 H⁺ + OH⁻ → H₂O，此反應必放熱（實證檢核：當莫耳數 n(H⁺) = n(OH⁻) 時恰好完全中和；中和點不一定等於 pH=7（看鹽類水解））。\n2. 酸鹼指示劑變色：石蕊（酸紅鹼藍）、酚酞（酸性/中性無色，鹼性粉紅/紅色）（實證檢核：以強鹼滴定強酸時，滴入酚酞，溶液由無色變粉紅色且 30 秒不褪色即終點）。\n3. 關鍵推理原則：酸鹼中和反應本質為 H⁺＋OH⁻→H₂O，必為放熱反應。酸鹼滴定利用已知濃度之酸（或鹼）測定未知濃度之鹼（或酸），當莫耳數相等時達到當量點，以酚酞（酸性無色、鹼性紅）或石蕊等指示劑判斷滴定終點。生活常見鹽類：氯化鈉（調味保鮮）、碳酸鈣（大理石石灰石主要成分）、碳酸氫鈉（小蘇打，烘焙加熱產生 CO₂）。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】1. 先針對題幹核心問題「做麵包或餅乾時常加入的「小蘇打粉」，受熱後能產生氣體使食品蓬鬆，其主要化學成分是？」進行分析：小蘇打為碳酸氫鈉（NaHCO₃），受熱易分解產生二氧化碳（CO₂）氣體、水與碳酸鈉。\n2. 核對各選項與課綱判準：選項 (B) 準確指出「碳酸氫鈉（NaHCO₃）」之結論，並完整扣合「酸鹼中和反應」與「酸鹼指示劑變色」的成立條件。\n3. 驗證遷移情境：不能跨不同濃度樣品直接用體積比；真實操作須使用防護並依教師指導，確認選項 (B) 推論嚴密無誤。",
