        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱「常見有機化合物與石化燃料」核心知識點：\n1. 烴類（碳氫化合物）：僅由碳與氫組成；甲烷 (CH₄)、丙烷 (C₃H₈)、丁烷 (C₄H₁₀)（實證檢核：天然氣主成分甲烷；液化石油氣（桶裝瓦斯）主成分丙烷與丁烷）。\n2. 完全與不完全燃燒：氧氣充足生成 CO₂ 與 H₂O；氧氣不足生成有毒 CO 與炭粒（實證檢核：室內使用熱水器需嚴防通風不良致一氧化碳中毒）。\n3. 關鍵推理原則：含碳化合物多為有機化合物（CO、CO₂、碳酸鹽與氰化物等除外）。烴類僅由碳氫組成：烷類單鍵、甲烷（CH₄）為天然氣主要成分、丙烷（C₃H₈）與丁烷為液化石油氣成分。醇類含羥基（—OH），乙醇（酒精）可溶於水作溶劑與消毒劑；有機酸含羧基（—COOH），乙酸（醋酸）具酸性。醇與酸在濃硫酸催化下發生酯化反應生成具香味的酯類與水。",
