        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱「地層順序與地質歷史判讀」核心知識點：\n1. 地層疊置定律：未經倒轉的沉積地層中，先沉積的在下（老），後沉積的在上（新）（實證檢核：判讀前先依沉積構造（如波痕、交錯層、遞變層）確認是否倒轉）。\n2. 切割與包裹律：被切割的岩層較老，切割者（岩脈或斷層）較新；包裹體比圍岩更老（實證檢核：岩脈貫穿砂岩層，岩脈較晚冷卻凝固；礫岩中的礫石比沉積岩基質老）。\n3. 關鍵推理原則：地質學家透過地層與化石推斷地球歷史。疊置定律指出未受擾動沉積岩下老上新；截切定律指出截切岩層的斷層或岩脈必定比被截切的岩層年輕；包裹定律指出岩石中所含的包裹塊必定比母岩古老。標準化石（分布廣、生存時期短、特徵明顯）可用於劃定地質年代（如三葉蟲為古生代、菊石恐龍為中生代）。",
