        "【第 5 步：版本對照 · 跨版本教材提點與大考心法】康軒、翰林、南一三版本教材在「地層順序與地質歷史判讀」均強調實作檢核任務：「畫出一個包含沉積岩層 A、B、C 及侵入岩脈 D 和斷層 E 的地質剖面圖，排出各事件發生的先後順序並解釋依據」。大考遇到跨圖表或情境素養題時，務必先劃出「地層疊置定律」與「切割與包裹律」的成立條件，再排除違反「地層若經歷強烈造山運動發生地層倒轉，則疊置定律必須配合沉…」的誘答選項。"
