        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱「天體引力、潮汐現象與月相變化」核心知識點：\n1. 月球自轉公轉同步：月球自轉週期等於繞地公轉週期（約 27.3 天），受潮汐鎖定，在地球上永遠只能看見同一面（實證檢核：月球面向地球的半球受陽光照射比例每日改變，產生由新月到滿月的規律月相週期（朔望月約 29.5 天））。\n2. 四大代表月相判讀：初一朔（月在日地中間，不可見）；初七八上弦月（西半亮半圓）；十五望滿月（整面亮）；廿二三下弦月（東半亮）（實證檢核：上弦月正午升起半夜落入西方；滿月傍晚自東方升起整夜可見；下弦月半夜升起中午西落）。\n3. 關鍵推理原則：潮汐主要是月球與太陽對地球海水的引潮力（萬有引力差）引起的週期性升降。海水面升到最高為滿潮，降到最低為乾潮，滿潮與乾潮之水位差為潮差。新月（農曆初一）與滿月（農曆十五）時太陽、地球、月球三者大致成一直線，引潮力相加形成「大潮」；上弦月與下弦月時日地月成垂直直角，引潮力部分抵消形成「小潮」。",
