        "【第 5 步：版本對照 · 跨版本教材提點與大考心法】康軒、翰林、南一三版本教材在「天體引力、潮汐現象與月相變化」均強調實作檢核任務：「查詢離你最近的海邊潮汐預報表，找出未來三天的滿潮與乾潮時間，計算潮差大小並推算當天月相」。大考遇到跨圖表或情境素養題時，務必先劃出「月球自轉公轉同步」與「四大代表月相判讀」的成立條件，再排除違反「潮汐週期不是剛好 12 小時，因為月球繞地球公轉，每天滿…」的誘答選項。"
