      "stem": "閱讀以下「人體消化器官與各類消化酵素專一性作用」之跨情境探究案例與對照資料：\n【情境案例與數據觀察】將「膽汁把脂肪直接分解成小分子，所以膽汁是一種酵素」改正。\n【延伸實證紀錄】吃下一口米飯在口中細嚼變甜，是唾液澱粉酶將澱粉分解成麥芽糖；吃牛排時蛋白質在胃中經胃蛋白酶初步分解，進入小腸後由胰蛋白酶與腸胜肽酶分解為小分子胺基酸被絨毛吸收。\n根據 108 課綱「生物」核心知識點與判準，針對上述情境及「人體消化管中，同時具有分解「醣類、蛋白質與脂質」三種主要營養素酵素的消化液是？」之綜合判斷，下列敘述何者最為正確？",
