        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱「光的折射定律與透鏡成像規律」核心知識點：\n1. 平面鏡反射成像：反射定律（入射角 = 反射角）；成「等大、正立、左右相反」的虛像，物距 = 像距（實證檢核：身高 160 cm 的人，只需 80 cm（身高一半）的直立平面鏡即可看到全身像）。\n2. 凹透鏡光學特性：對光線具發散作用，不論物體放在鏡前何處，恆成「正立、縮小、虛像」於物同側（實證檢核：近視眼鏡鏡片即為凹透鏡，利用發散作用將眼球過早匯聚的光線焦點後移至視網膜上）。\n3. 關鍵推理原則：光由光速較快的介質斜向射入光速較慢的介質時（如空氣進入玻璃或水），折射光線偏向法線（折射角小於入射角）。凸透鏡成像：物距在兩倍焦距外成倒立縮小實像（照相機原理）；在一倍與兩倍焦距間成倒立放大實像（投影機原理）；在焦點內成正立放大虛像（放大鏡原理）。凹透鏡恆成正立縮小虛像（近視眼鏡原理）。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】1. 先針對題幹核心問題「筷子斜插入裝滿清水的透明玻璃杯中，從水面上方觀察，筷子在水中的部分看起來會？」進行分析：光由水中進入空氣折射偏離法線，人眼逆著光線看過去，水中筷子的各點成像位置比實際位置偏高，看起來向上彎折變淺。\n2. 核對各選項與課綱判準：選項 (B) 準確指出「向上彎折且看起來變淺」之結論，並完整扣合「平面鏡反射成像」與「凹透鏡光學特性」的成立條件。\n3. 驗證遷移情境：不能把「放大」與「虛像」當成同義；中間位置會產生放大的實像，確認選項 (B) 推論嚴密無誤。",
