        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱「動能、重力位能與力學能守恆定律」核心知識點：\n1. 動能公式與特性：Ek = (1/2)mv²；動能與質量 m 成正比，與運動速率 v 的平方成正比（實證檢核：汽車車速由 30 km/h 增至 60 km/h（速度變 2 倍），煞車時所需煞車距離將暴增為 4 倍）。\n2. 重力位能差：Ep = mgh；位能具有相對性，必須先選定零位能參考基準面，位能變化量 ΔEp 則為絕對（實證檢核：自 10 公尺高掉落至 2 公尺處，重力做功 W = mgΔh = mg(8)，重力位能減少並完全轉化為動能）。\n3. 關鍵推理原則：物體因運動具有的能量稱為動能（Ek＝½mv²，與質量成正比、與速率平方成正比）。物體因位置高度具有的能量為重力位能（Ep＝mgh，與質量及高度成正比）。在只有重力作功、沒有摩擦阻力的封閉系統中，動能與位能的總和維持定值（力學能守恆：Ek＋Ep＝常數）。",
